using System.ComponentModel.DataAnnotations;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(50)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }

    [MaxLength(256)]
    public string CustomerEmail { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToDto(entity);
    }

    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                entity.ActualDelivery = DateTime.UtcNow;
            await db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

using Microsoft.AspNetCore.Identity;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await db.Database.EnsureCreatedAsync();

        if (db.Shipments.Any()) return;

        // Seed roles
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
        if (!await roleManager.RoleExistsAsync("Dispatcher"))
            await roleManager.CreateAsync(new IdentityRole("Dispatcher"));
        if (!await roleManager.RoleExistsAsync("Customer"))
            await roleManager.CreateAsync(new IdentityRole("Customer"));

        // Seed sample shipments
        db.Shipments.AddRange(
            new Shipment
            {
                TrackingNumber = "TRK-001-2026",
                Origin = "New York, USA",
                Destination = "London, UK",
                Status = ShipmentStatus.InTransit,
                ShippedDate = DateTime.UtcNow.AddDays(-3),
                EstimatedDelivery = DateTime.UtcNow.AddDays(4),
                CustomerEmail = "customer@example.com",
                Description = "Electronics - Laptop"
            },
            new Shipment
            {
                TrackingNumber = "TRK-002-2026",
                Origin = "Shanghai, China",
                Destination = "Berlin, Germany",
                Status = ShipmentStatus.PickedUp,
                ShippedDate = DateTime.UtcNow.AddDays(-1),
                EstimatedDelivery = DateTime.UtcNow.AddDays(7),
                CustomerEmail = "customer@example.com",
                Description = "Automotive Parts"
            },
            new Shipment
            {
                TrackingNumber = "TRK-003-2026",
                Origin = "Tokyo, Japan",
                Destination = "Sydney, Australia",
                Status = ShipmentStatus.OutForDelivery,
                ShippedDate = DateTime.UtcNow.AddDays(-5),
                EstimatedDelivery = DateTime.UtcNow,
                CustomerEmail = "alice@example.com",
                Description = "Medical Supplies"
            },
            new Shipment
            {
                TrackingNumber = "TRK-004-2026",
                Origin = "São Paulo, Brazil",
                Destination = "Miami, USA",
                Status = ShipmentStatus.Delivered,
                ShippedDate = DateTime.UtcNow.AddDays(-10),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-3),
                CustomerEmail = "bob@example.com",
                Description = "Coffee Beans - Premium"
            },
            new Shipment
            {
                TrackingNumber = "TRK-005-2026",
                Origin = "Mumbai, India",
                Destination = "Toronto, Canada",
                Status = ShipmentStatus.Exception,
                ShippedDate = DateTime.UtcNow.AddDays(-6),
                EstimatedDelivery = DateTime.UtcNow.AddDays(1),
                CustomerEmail = "alice@example.com",
                Description = "Textiles - Silk Fabric"
            }
        );

        await db.SaveChangesAsync();
    }
}

using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            await service.GetAllShipmentsAsync());

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            await service.GetShipmentsForCustomerAsync(email));

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, newStatus);
            return Results.NoContent();
        }).RequireAuthorization("DispatcherPolicy");
    }
}

